// Two OuterNamedGate instances (named custom Bloq, must resolve to the same shared Circuit), an
// anonymous 3-level CompositeBloq nesting, and two MyGateWithCZPow instances (each forwarding its
// own scratch ancilla to the root's anc_clean pool without colliding).
TEST(QualtranFrontend, SubcircuitVariants) {
    QualtranFixture fx("subcircuit_variants");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(12u, func->GetNumQubits());
    EXPECT_EQ(10u, func->GetInstructionCount());

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();

    EXPECT_TRUE(Next(itr, bb)->IsOptHint());
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());

    // Two OuterNamedGate instances: same underlying bloq, must resolve to the same Function.
    const ir::Function* outer_a = ExpectCallOperands(Next(itr, bb), {0, 1});
    const ir::Function* outer_b = ExpectCallOperands(Next(itr, bb), {2, 3});
    EXPECT_EQ(outer_a, outer_b);
    ASSERT_NE(outer_a, nullptr);
    EXPECT_NE(std::string::npos, std::string(outer_a->GetName()).find("OuterNamedGate"));
    EXPECT_EQ(2u, outer_a->GetNumQubits());
    EXPECT_EQ(3u, outer_a->GetInstructionCount());  // X + Call(InnerNamedGate) + Return

    // Anonymous 3-level nesting (outer->middle->inner).
    {
        const ir::Function* mid_func = ExpectCallOperands(Next(itr, bb), {4, 5});
        EXPECT_EQ(2u, mid_func->GetNumQubits());
        EXPECT_EQ(3u, mid_func->GetInstructionCount());  // H + Call(inner) + Return
    }

    // Two MyGateWithCZPow instances: distinct Functions despite the same underlying bloq name,
    // each forwarding its own CZPowGate scratch ancilla to the root's anc_clean pool.
    const ir::Function* sub_a = ExpectCallOperands(Next(itr, bb), {6, 7, 10});
    const ir::Function* sub_b = ExpectCallOperands(Next(itr, bb), {8, 9, 11});
    ASSERT_NE(sub_a, nullptr);
    ASSERT_NE(sub_b, nullptr);
    EXPECT_NE(sub_a, sub_b);
    for (const ir::Function* sub_func : {sub_a, sub_b}) {
        EXPECT_EQ(3u, sub_func->GetNumQubits());
        EXPECT_EQ(4u, sub_func->GetInstructionCount());  // Clean + Call(CZPowGate) + Clean + Return
    }

    EXPECT_TRUE(Next(itr, bb)->IsOptHint());
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());
    EXPECT_EQ(ir::Opcode::Table::Return, Next(itr, bb)->GetOpcode().GetCode());
    EXPECT_EQ(itr, bb->end());
}

// Every AdjointWrapper scenario: custom composite reversal, self-adjoint preset, inlined Gate
// terminal, name resolution across differently-parameterized instances, even/odd nesting depth,
// AliasOnly, a composite with its own CleanAncilla, and Producer/Consumer role flip.
TEST(QualtranFrontend, AdjointVariants) {
    QualtranFixture fx("adjoint_variants");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(22u, func->GetNumQubits());
    EXPECT_EQ(27u, func->GetInstructionCount());

    constexpr double kEps = 1e-8;

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();

    // anc_clean holds all three And-pair/CleanAncilla scratch qubits below; there is no
    // anc_operate pool (nothing here needs it).
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(anc_clean[0])
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(anc_clean[1])
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(anc_clean[2])

    // Adjoint(MyGate()): reversed order (H, X).
    {
        const ir::Function* adj_func = ExpectCallOperands(Next(itr, bb), {0});
        EXPECT_EQ(1u, adj_func->GetNumQubits());
        EXPECT_EQ(3u, adj_func->GetInstructionCount());
        const ir::BasicBlock* adj_bb = adj_func->GetEntryBB();
        auto adj_itr = adj_bb->begin();
        ExpectInstruction(Next(adj_itr, adj_bb), ir::Opcode::Table::H, {0});
        ExpectInstruction(Next(adj_itr, adj_bb), ir::Opcode::Table::X, {0});
        EXPECT_EQ(ir::Opcode::Table::Return, Next(adj_itr, adj_bb)->GetOpcode().GetCode());
    }

    // Adjoint(CHadamard()): self-adjoint, unreversed order.
    {
        const ir::Function* ch_func = ExpectCallOperands(Next(itr, bb), {1, 2});
        EXPECT_EQ(2u, ch_func->GetNumQubits());
        EXPECT_EQ(8u, ch_func->GetInstructionCount());
    }

    // Adjoint(CRz(angle=0.3, eps=1e-8)): inlined, angle negated: RZ(-0.15)-CX-RZ(0.15)-CX.
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 4u, -0.15, kEps / 2.0);
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {4, 3});
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 4u, 0.15, kEps / 2.0);
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {4, 3});

    // Adjoint(MyRzGate(angle=0.3)) and Adjoint(MyRzGate(angle=0.7)): distinct Circuits, each
    // with its own angle negated -- neither collides nor swaps its angle with the other.
    {
        const ir::Function* rz_a = ExpectCallOperands(Next(itr, bb), {5});
        EXPECT_NE(std::string::npos, std::string(rz_a->GetName()).find("MyRzGate"));
        EXPECT_EQ(2u, rz_a->GetInstructionCount());  // RZ + Return
        ExpectRotation(rz_a->GetEntryBB()->begin().GetPointer(), ir::Opcode::Table::RZ, 0u, -0.3, kEps);

        const ir::Function* rz_b = ExpectCallOperands(Next(itr, bb), {6});
        EXPECT_NE(std::string::npos, std::string(rz_b->GetName()).find("MyRzGate"));
        EXPECT_EQ(2u, rz_b->GetInstructionCount());
        ExpectRotation(rz_b->GetEntryBB()->begin().GetPointer(), ir::Opcode::Table::RZ, 0u, -0.7, kEps);

        EXPECT_NE(rz_a, rz_b);
    }

    // Adjoint(SU2RotationGate(theta, phi, lambd, global_shift)): same params as parametrized_gates'
    // non-adjoint case, for direct comparison. Mirrors EmitSU2RotationGate's own formula with
    // phi/lambd swapped and negated, global_shift negated, and theta untouched (matches
    // EmitGate's is_adjoint dispatch for SU2RotationGate).
    constexpr auto kSu2Theta = 0.1;
    constexpr auto kSu2Phi = 0.2;
    constexpr auto kSu2Lambd = 0.3;
    constexpr auto kSu2GlobalShift = 0.4;
    constexpr auto kSu2AdjPhi = -kSu2Lambd;
    constexpr auto kSu2AdjLambd = -kSu2Phi;
    constexpr auto kSu2AdjGlobalShift = -kSu2GlobalShift;
    ExpectGlobalPhase(
            Next(itr, bb),
            0.5 + kSu2AdjGlobalShift / std::numbers::pi
                    + kSu2AdjLambd / (2.0 * std::numbers::pi)
                    + kSu2AdjPhi / (2.0 * std::numbers::pi),
            kEps
    );
    ExpectRotation(
            Next(itr, bb),
            ir::Opcode::Table::RZ,
            7u,
            std::numbers::pi / 2.0 - kSu2AdjLambd,
            kEps / 3.0
    );
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RX, 7u, 2.0 * kSu2Theta, kEps / 3.0);
    ExpectRotation(
            Next(itr, bb),
            ir::Opcode::Table::RZ,
            7u,
            std::numbers::pi / 2.0 - kSu2AdjPhi,
            kEps / 3.0
    );

    // Adjoint(Rz(angle=pi/4)): inlined via the shared `sign` dispatch, angle negated.
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 8u, -std::numbers::pi / 4.0, kEps);

    // Even (2-layer) Adjoint(Adjoint(And())) resolves back to compute direction.
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {9, 10, 19})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {9, 10, 19})->GetName())
    );

    // Odd (3-layer) Adjoint(Adjoint(Adjoint(And()))) flips to uncompute direction: same
    // producer/consumer shape as the even case above, so its ancilla is Clean too (anc_clean[1]).
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {11, 12, 20})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {11, 12, 20})->GetName())
    );

    // Adjoint(Split(...)) is AliasOnly: no gate for x_split (qubits 13, 14 never appear).

    // Adjoint(AndWithGatesGate()): custom composite with its own CleanAncilla (anc_clean[2]).
    {
        const ir::Function* adj_func = ExpectCallOperands(Next(itr, bb), {15, 16, 21});
        EXPECT_EQ(3u, adj_func->GetNumQubits());
        EXPECT_EQ(6u, adj_func->GetInstructionCount());
    }

    // Adjoint(ZeroState())/Adjoint(ZeroEffect()): both flip to MarkAsClean (odd depth).
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(q_state)
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(q_effect)

    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(anc_clean[0]), end of scope
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(anc_clean[1]), end of scope
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // Clean(anc_clean[2]), end of scope
    EXPECT_EQ(ir::Opcode::Table::Return, Next(itr, bb)->GetOpcode().GetCode());
    EXPECT_EQ(itr, bb->end());
}

// Adjoint(MyGate()) serialized at max_depth=2, so Qualtran expands the Adjoint wrapper itself
