// Every ControlledWrapper scenario: N=1 direct dispatch, exact-gate-via-And synthesis, rotation
// and GlobalPhase controls, multi-bit and negative-control AND-ladders, nested Controlled, and a
// decomposable sub-circuit.
TEST(QualtranFrontend, ControlledVariants) {
    QualtranFixture fx("controlled_variants");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(25u, func->GetNumQubits());

    constexpr double kEps = 1e-8;

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();

    for (auto i = 0u; i < 9; ++i) {
        EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // 9 anc_clean Clean hints, one per AND-ladder use.
    }

    // Controlled(XGate()) -> CX.
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {1, 0});
    // Controlled(Hadamard()) -> CHadamard preset call.
    EXPECT_EQ("CHadamard", std::string(ExpectCallOperands(Next(itr, bb), {0, 1})->GetName()));

    // Controlled(TGate()) -> And(compute)-T-And(uncompute).
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {1, 0, 16})->GetName())
    );
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::T, {16});
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {1, 0, 16})->GetName())
    );

    // Controlled(TGate(is_adjoint=True)) -> And(compute)-TDag-And(uncompute).
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {1, 0, 17})->GetName())
    );
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::TDag, {17});
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {1, 0, 17})->GetName())
    );

    // Controlled(Adjoint(TGate())) -> throwaway-Circuit(And(compute)-TDag-And(uncompute))
    // + ReplaceWithAdjoint, dispatched via a __adjoint____controlled__ Call.
    {
        const ir::Function* adj_func = ExpectCallOperands(Next(itr, bb), {0, 1, 18});
        EXPECT_EQ(3u, adj_func->GetNumQubits());
        EXPECT_EQ(4u, adj_func->GetInstructionCount());  // And(compute)+TDag+And(uncompute)+Return
        const ir::BasicBlock* adj_bb = adj_func->GetEntryBB();
        auto adj_itr = adj_bb->begin();
        EXPECT_EQ(
                "And_cv11__compute",
                std::string(ExpectCallOperands(Next(adj_itr, adj_bb), {1, 0, 2})->GetName())
        );
        ExpectInstruction(Next(adj_itr, adj_bb), ir::Opcode::Table::TDag, {2});
        EXPECT_EQ(
                "And_cv11__uncompute",
                std::string(ExpectCallOperands(Next(adj_itr, adj_bb), {1, 0, 2})->GetName())
        );
    }

    // Controlled(XPowGate(exponent=0.5)) -> EmitCXPowGate.
    constexpr auto kQuarterTurn = std::numbers::pi / 4;
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::H, {1});
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 1, kQuarterTurn, kEps / 2);
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {1, 0});
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 1, -kQuarterTurn, kEps / 2);
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {1, 0});
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::H, {1});
    ExpectGlobalPhase(Next(itr, bb), 0.125, kEps);
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 0, kQuarterTurn, kEps);

    // Controlled(Rz(angle=pi/4)) -> RZ-CX-RZ-CX.
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 1u, kQuarterTurn / 2.0, kEps / 2.0);
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {1, 0});
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 1u, -kQuarterTurn / 2.0, kEps / 2.0);
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {1, 0});

    // Controlled(GlobalPhase(exponent=0.3)) -> GlobalPhase + RZ on ctrl itself.
    ExpectGlobalPhase(Next(itr, bb), 0.15, kEps);
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 0u, std::numbers::pi * 0.3, kEps);

    // Controlled(XGate(), cvs=0): N=1 negative control, X-wraps ctrl.
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::X, {0});
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {1, 0});
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::X, {0});

    // Controlled(MyGate()): a decomposable sub-circuit dispatched via a __controlled__ Call.
    {
        const ir::Function* sub_func = ExpectCallOperands(Next(itr, bb), {0, 1});
        EXPECT_EQ(2u, sub_func->GetNumQubits());
        EXPECT_EQ(3u, sub_func->GetInstructionCount());  // CX + Call(CHadamard) + Return
        const ir::BasicBlock* sub_bb = sub_func->GetEntryBB();
        auto si = sub_bb->begin();
        ExpectInstruction(Next(si, sub_bb), ir::Opcode::Table::CX, {1, 0});
        EXPECT_EQ(
                "CHadamard", std::string(ExpectCallOperands(Next(si, sub_bb), {0, 1})->GetName())
        );
    }

    // Controlled(CNOT()) -> CCX.
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CCX, {4, 2, 3});

    // Controlled(XGate(), cvs=[1,0,1]): N=3 AND-ladder.
    EXPECT_EQ(
            "And_cv10__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {5, 6, 19})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {19, 7, 20})->GetName())
    );
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {8, 20});
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {19, 7, 20})->GetName())
    );
    EXPECT_EQ(
            "And_cv10__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {5, 6, 19})->GetName())
    );

    // Controlled(Toffoli()): AND-ladder extended by Toffoli's own 2 ctrl qubits.
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {9, 10, 21})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {21, 11, 22})->GetName())
    );
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::CX, {12, 22});
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {21, 11, 22})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {9, 10, 21})->GetName())
    );

    // Controlled(Controlled(TGate())): nested, equivalent to one 2-bit AND control.
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {13, 14, 23})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {15, 23, 24})->GetName())
    );
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::T, {24});
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {15, 23, 24})->GetName())
    );
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {13, 14, 23})->GetName())
    );

    for (auto i = 0u; i < 9; ++i) {
        EXPECT_TRUE(Next(itr, bb)->IsOptHint());  // 9 anc_clean Clean hints, end of scope.
    }
    EXPECT_EQ(ir::Opcode::Table::Return, Next(itr, bb)->GetOpcode().GetCode());
    EXPECT_EQ(itr, bb->end());
}

// EmitBloqCounts always materializes bloq_counts entries right before Return, regardless of their
// source-order interleaving with regular decomposition instructions. ArbitraryCliffordSource is a
// custom Bloq reporting ArbitraryClifford via bloq_counts without IntState, so this doesn't depend
// on IntState's own decomposition; its LOG_WARN "not already emitted via decomposition" branch
// fires but isn't asserted. bloq_counts is a protobuf map, so GlobalPhase order isn't guaranteed
// -- checked as a multiset.
TEST(QualtranFrontend, BloqCountsVariants) {
    QualtranFixture fx("bloq_counts_variants");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(1u, func->GetNumQubits());
    EXPECT_EQ(7u, func->GetInstructionCount());  // X, X, Call(ArbitraryCliffordSource), 3 x
                                                  // GlobalPhase, Return.

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();

    // Two X gates from the decomposition, materialized in source order (unlike GlobalPhase).
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::X, {0});
    ExpectInstruction(Next(itr, bb), ir::Opcode::Table::X, {0});

    // ArbitraryCliffordSource() itself converts to a Call into a Circuit containing a single X.
    {
        const ir::Function* sub_func = ExpectCallOperands(Next(itr, bb), {0});
        EXPECT_EQ(2u, sub_func->GetInstructionCount());  // X + Return
        ExpectInstruction(sub_func->GetEntryBB()->begin().GetPointer(), ir::Opcode::Table::X, {0});
    }

    // All 3 bloq_counts GlobalPhase entries, materialized last regardless of their source-order
    // interleaving with the X gates and the ArbitraryCliffordSource() call above.
    auto phases = std::vector<double>{};
    for (auto i = 0u; i < 3; ++i) {
        const ir::Instruction* inst = Next(itr, bb);
        ASSERT_EQ(ir::Opcode::Table::GlobalPhase, inst->GetOpcode().GetCode());
        const auto* gp = Cast<ir::GlobalPhaseInst>(inst);
        EXPECT_NEAR(1e-8, gp->GetTheta().precision, kTol);
        phases.push_back(gp->GetTheta().value);
    }
    std::ranges::sort(phases);
    EXPECT_NEAR(0.25, phases[0], kTol);
    EXPECT_NEAR(0.5, phases[1], kTol);
    EXPECT_NEAR(0.5, phases[2], kTol);

    EXPECT_EQ(ir::Opcode::Table::Return, Next(itr, bb)->GetOpcode().GetCode());
    EXPECT_EQ(itr, bb->end());
}

// LeafRoot fixtures: root itself is atomic (decomposition_size() == 0), one per bloq kind that
// can plausibly appear standalone as a root. Bookkeeping bloqs are not expected to appear
// standalone as a root and are already covered by regression tests elsewhere.

// A directly-mapped gate as root (no ancilla, no synthesis).
TEST(QualtranFrontend, LeafRootHadamard) {
    QualtranFixture fx("leaf_root_hadamard");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(1u, func->GetNumQubits());
    EXPECT_EQ(2u, func->GetInstructionCount());

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();
    const ir::Instruction* inst = Next(itr, bb);
    ASSERT_TRUE(inst->IsUnary());
    EXPECT_EQ(ir::Opcode::Table::H, inst->GetOpcode().GetCode());
    EXPECT_EQ(0u, Cast<ir::UnaryInst>(inst)->GetQubit().id);
}

// A preset CircuitGenerator gate as root (dispatches via a Call, not an inline sequence).
TEST(QualtranFrontend, LeafRootPreset) {
    QualtranFixture fx("leaf_root_preset");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(2u, func->GetNumQubits());
    EXPECT_EQ(2u, func->GetInstructionCount());  // Call(CHadamard) + Return

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();
    const ir::Function* ch_func = ExpectCallOperands(Next(itr, bb), {0, 1});
    EXPECT_EQ("CHadamard", std::string(ch_func->GetName()));
    EXPECT_EQ(ir::Opcode::Table::Return, Next(itr, bb)->GetOpcode().GetCode());
}

// CZPowGate as root: a Gate terminal needing its own scratch ancilla.
TEST(QualtranFrontend, LeafRootCzpow) {
    QualtranFixture fx("leaf_root_czpow");
    auto* circuit = fx.Build();

    ASSERT_NE(circuit, nullptr);
    const ir::Function* func = circuit->GetIR();
    ASSERT_NE(func, nullptr);

    EXPECT_EQ(3u, func->GetNumQubits());  // q[2] + anc_clean.
    EXPECT_EQ(7u, func->GetInstructionCount());

    constexpr double kExp = 0.5;
    constexpr double kEps = 1e-8;

    const ir::BasicBlock* bb = func->GetEntryBB();
    ASSERT_NE(bb, nullptr);
    auto itr = bb->begin();

    EXPECT_TRUE(Next(itr, bb)->IsOptHint());
    EXPECT_EQ(
            "And_cv11__compute",
            std::string(ExpectCallOperands(Next(itr, bb), {0, 1, 2})->GetName())
    );
    ExpectGlobalPhase(Next(itr, bb), kExp / 2.0, kEps);
    ExpectRotation(Next(itr, bb), ir::Opcode::Table::RZ, 2u, std::numbers::pi * kExp, kEps);
    EXPECT_EQ(
            "And_cv11__uncompute",
            std::string(ExpectCallOperands(Next(itr, bb), {0, 1, 2})->GetName())
    );
    EXPECT_TRUE(Next(itr, bb)->IsOptHint());
    EXPECT_EQ(ir::Opcode::Table::Return, Next(itr, bb)->GetOpcode().GetCode());
}

// And() as root: a NewQubitProducer Gate terminal, its own ancilla produced fresh rather than
// forwarded from an existing pool (unlike LeafRootCzpow's).
